(function(){
'use strict';
const area=document.getElementById('workspace-content'),repo=window.DaydreamRepository,esc=window.DaydreamDB.escape,get=id=>document.getElementById(id),Recognition=window.SpeechRecognition||window.webkitSpeechRecognition;
let current=null,draft={name:'',text:''},dirty=false,revision=0,timer,speech,liveVoice=null,consented=false,chain=Promise.resolve();
function status(text,error=false){const el=get('capture-save-status');if(el){el.textContent=text;el.classList.toggle('save-error',error);}}
function speechStatus(text,error=false){const el=get('speech-status');if(el){el.textContent=text;el.classList.toggle('save-error',error);}}
function stopSpeech(){speech?.abort();speech=null;}
function changed(){dirty=true;revision++;status('');clearTimeout(timer);timer=setTimeout(flush,650);}
async function flush(){clearTimeout(timer);if(!dirty)return chain.then(()=>true);if(!draft.text.trim()&&!current){dirty=false;return true;}const rev=revision,copy={...draft,id:current?.id,createdAt:current?.createdAt,assignment:current?.assignment};status('');chain=chain.catch(()=>{}).then(()=>repo.saveCapture({...copy,id:copy.id||current?.id,createdAt:copy.createdAt||current?.createdAt}));try{const saved=await chain;current=saved;if(rev===revision){dirty=false;status('Saved');}return true;}catch(err){status(`Not saved: ${err.message}. Your text is still here.`,true);return false;}}
async function render(){if(window.DaydreamAuth&&!window.DaydreamAuth.user){window.DaydreamAuth.require('#capture');return;}stopSpeech();try{await repo.open();const captures=await repo.all('captures');const last=window.DaydreamWorkspace?.context?.().reality;const world=last?await repo.get('realities',last.id):null;if(current&&!dirty){current=captures.find(c=>c.id===current.id)||null;draft=current?{name:current.name,text:current.text}:{name:'',text:''};}
area.innerHTML=`${window.DaydreamWorkspaceUI.header({world,mode:'capture'})}<div class="capture-heading"><h1>Catch the thought.</h1><p>Type a few words, or speak them aloud. Find a place for them later.</p></div><div class="capture-layout"><section class="capture-writing" aria-label="Capture editor"><div class="capture-editor-toolbar"><button class="text-button" data-capture-action="new">New capture</button></div><label for="capture-name">Name <span>(optional)</span></label><input id="capture-name" maxlength="200" value="${esc(draft.name)}" placeholder="A passing thought"><label for="capture-text">Your thought or transcript</label><div class="capture-input-wrap"><textarea id="capture-text" dir="auto" placeholder="A scene, a conversation, a place…">${esc(draft.text)}</textarea>${Recognition?`<div class="capture-voice-tools"><span id="speech-status" role="status" aria-live="polite"></span><select id="speech-language" aria-label="Dictation language"><option value="en-US">English (US)</option><option value="en-GB">English (UK)</option><option value="ur-PK">Urdu</option></select><button type="button" class="capture-mic" id="voice-start" data-capture-action="voice" aria-label="Start dictation" title="Start dictation"><svg viewBox="0 0 24 24" aria-hidden="true"><rect x="9" y="3" width="6" height="12" rx="3"/><path d="M6 11v1a6 6 0 0 0 12 0v-1M12 18v3m-4 0h8"/></svg></button><button type="button" class="capture-mic" id="voice-stop" data-capture-action="stop" aria-label="Stop dictation" title="Stop dictation" hidden><svg viewBox="0 0 24 24" aria-hidden="true"><rect x="6" y="6" width="12" height="12" rx="2"/></svg></button></div>`:''}</div>${Recognition?'':'<p class="speech-fallback">Type, paste, or use your keyboard’s dictation.</p>'}<div class="capture-actions"><button class="secondary-button" data-capture-action="assign">Place in a reality</button>${current?'<button class="delete-button" data-capture-action="delete">Delete capture</button>':''}</div><p id="capture-save-status" role="status" aria-live="polite"></p>${current?.assignment?`<p>A copy was placed in <a href="#world/${encodeURIComponent(current.assignment.worldId)}">your reality</a>. Editing this capture does not change that copy.</p>`:''}</section><aside class="capture-library"><div class="panel-title"><h2>Your captures</h2><span>${captures.length}</span></div>${captures.slice().reverse().map(c=>`<button class="capture-card ${current?.id===c.id?'selected':''}" data-capture-id="${esc(c.id)}"><span>${esc(c.name)}</span><p>${esc(c.text.slice(0,125))}</p><small>${c.assignment?'Placed':'Unassigned'}</small></button>`).join('')||'<p>No captures yet. Save your first thought.</p>'}</aside></div>`;document.title='Dream Capture — Daydream';}catch(err){area.innerHTML=`<p class="storage-error" role="alert">${esc(err.message)}</p>`;}}
const consent=document.createElement('dialog');consent.setAttribute('aria-labelledby','speech-consent-title');consent.innerHTML='<h2 id="speech-consent-title">Voice capture</h2><p>Your browser may send audio to its speech provider. Only the transcript is saved in Daydream.</p><div class="dialog-actions"><button class="secondary-button" id="speech-cancel">Cancel</button><button class="button" id="speech-allow">Start microphone</button></div>';document.body.append(consent);get('speech-cancel').onclick=()=>consent.close();get('speech-allow').onclick=()=>{consent.close();consented=true;startSpeech();};
function paintVoice(){
 const v=liveVoice,field=get('capture-text');if(!v||!field)return;
 const spoken=[...v.final,v.interim].filter(Boolean).join(' ');
 const text=v.before+(v.before&&spoken&&!/\s$/.test(v.before)?' ':'')+spoken+(v.after&&spoken&&!/^\s/.test(v.after)?' ':'')+v.after;
 if(field.value===text)return;
 draft.text=text;field.value=text;field.setSelectionRange(text.length-v.after.length,text.length-v.after.length);field.scrollTop=field.scrollHeight;changed();
}
function startSpeech(){
 const field=get('capture-text');liveVoice={before:field.value,after:'',final:[],interim:''};
 get('voice-start').hidden=true;get('voice-stop').hidden=false;get('speech-language').disabled=true;
 speech=new window.DaydreamSpeechInput(Recognition,{onText(text){if(!liveVoice)return;liveVoice.final.push(text);liveVoice.interim='';paintVoice();},onInterim(text){if(!liveVoice)return;liveVoice.interim=text;paintVoice();},onStatus:speechStatus,onEnd(){
  liveVoice=null;
  if(get('voice-start')){get('voice-start').hidden=false;get('voice-stop').hidden=true;get('speech-language').disabled=false;}
 }});
 try{speech.start(get('speech-language').value);}catch(err){liveVoice=null;speechStatus(err.message,true);get('voice-start').hidden=false;get('voice-stop').hidden=true;get('speech-language').disabled=false;}
}
const assignment=document.createElement('dialog');assignment.className='work-dialog';document.body.append(assignment);
async function assign(){const realities=await repo.all('realities');if(!current){status('Save a thought first.',true);return;}if(current.assignment){status('This capture has already been placed.');return;}if(!realities.length){status('Create an alternative reality first.',true);return;}
assignment.innerHTML=`<form><h2>Place your capture</h2><p>A copy goes into your reality. The original stays here.</p><label>Alternative reality<select name="reality">${realities.map(r=>`<option value="${esc(r.id)}">${esc(r.name)}</option>`).join('')}</select></label><label>Destination<select name="target"></select></label><label>New document function<select name="type">${Object.entries(window.DaydreamDB.TYPES).map(([k,v])=>`<option value="${k}" ${k==='note'?'selected':''}>${esc(v)}</option>`).join('')}</select></label><p class="modal-error" role="alert"></p><div class="dialog-actions"><button type="button" class="secondary-button" data-close>Cancel</button><button class="button">Place capture</button></div></form>`;
async function targets(){const list=await repo.all('catalog',assignment.querySelector('[name=reality]').value);assignment.querySelector('[name=target]').innerHTML='<option value="">Create a new document</option>'+list.filter(d=>!d.canvasType).map(d=>`<option value="${esc(d.id)}">Append to ${esc(d.name)}</option>`).join('');}await targets();assignment.querySelector('[name=reality]').onchange=targets;assignment.querySelector('[data-close]').onclick=()=>assignment.close();assignment.querySelector('form').onsubmit=async e=>{e.preventDefault();try{const f=new FormData(e.target);current=await repo.assignCapture(current.id,f.get('reality'),f.get('target'),f.get('type'));assignment.close();await render();status('Capture placed. The original is kept here.');}catch(err){assignment.querySelector('.modal-error').textContent=err.message;}};assignment.showModal();}
area.addEventListener('beforeinput',e=>{if(e.target.id==='capture-text'&&speech?.active){liveVoice=null;speech.stop();}});
area.addEventListener('input',e=>{if(['capture-name','capture-text'].includes(e.target.id)){draft={name:get('capture-name').value,text:get('capture-text').value};changed();}});
area.addEventListener('click',async e=>{const b=e.target.closest('[data-capture-action],[data-capture-id]');if(!b)return;try{const action=b.dataset.captureAction;if(action==='voice'){if(consented)startSpeech();else consent.showModal();return;}if(action==='stop'){await speech?.stop();await flush();return;}if(speech?.active){speech.stop();status('Microphone stopping. Review the transcript, then continue.');return;}if(!await flush())return;if(b.dataset.captureId){current=await repo.get('captures',b.dataset.captureId);await render();return;}if(action==='new'){current=null;draft={name:'',text:''};await render();get('capture-text').focus();}if(action==='save'){await render();status(current?(repo.status?.()||'Saved on this device'):'Write a thought before saving.');}if(action==='assign')await assign();if(action==='delete'&&confirm('Delete this capture? Copies placed in your reality will stay.')){await repo.batch([{table:'captures',remove:current.id}]);current=null;draft={name:'',text:''};await render();}}catch(err){status(err.message,true);}});
async function beforeNavigate(){if(speech?.active)await speech.stop();if(!await flush()) {history.replaceState(null,'','#capture');return false;}stopSpeech();return true;}
document.addEventListener('visibilitychange',()=>{if(document.hidden&&speech?.active)speech.stop().then(flush);});
window.addEventListener('beforeunload',e=>{if(dirty||speech?.active){e.preventDefault();e.returnValue='';}stopSpeech();});
window.DaydreamCapture={render,beforeNavigate,hasUnsaved:()=>dirty,reset(){consented=false;liveVoice=null;clearTimeout(timer);stopSpeech();consent.close();assignment.close();current=null;draft={name:'',text:''};dirty=false;revision++;chain=Promise.resolve();},prepareAction:async()=>{if(speech?.active){speech.stop();status('Review the transcript when the microphone stops.');return false;}return flush();}};
})();
